<template><div class="app-container"><div class="page-header"><div><h1>{{ definition.title }}</h1><p>{{ definition.description }}</p></div><div class="page-actions"><el-button icon="el-icon-refresh" @click="load">Refresh</el-button><interaction-notes :title="definition.title" :notes="definition.notes"/></div></div><el-form inline class="filter-container"><el-form-item><el-input v-model="search" placeholder="Search records" clearable class="search-input"/></el-form-item><el-form-item v-if="kind!=='audit' && kind!=='campaign-runs'"><el-select v-model="userId" clearable filterable placeholder="All users"><el-option v-for="user in users" :key="user.id" :label="user.name" :value="user.id"/></el-select></el-form-item><el-form-item><el-select v-model="status" clearable placeholder="All statuses"><el-option v-for="value in statuses" :key="value" :label="value" :value="value"/></el-select></el-form-item></el-form><div v-loading="loading"><records-table :kind="kind" :rows="pageRows" :show-user="kind!=='audit' && kind!=='campaign-runs'" @changed="load"/></div><div class="pagination-container"><el-pagination :current-page.sync="page" :page-size="10" :total="filtered.length" layout="total, prev, pager, next"/></div><el-alert v-if="error" :title="error" type="error" :closable="false"/></div></template>
<script>
import {listLedger,listOrders,listSubscriptions,listRedemptions,listUsage,listCampaignRuns,listAudit,listUsers} from '@/api/commerce'
import RecordsTable from '@/components/Commerce/RecordsTable'

import InteractionNotes from '@/components/InteractionNotes'
const definitions={
ledger:{title:'Credits Ledger',description:'Issued, reserved, released, spent and expired events.',loader:listLedger,notes:[{title:'流水口径',rule:'GRANT 入账；RESERVE 仅占用可用余额；SPEND 才是实际消耗；RELEASE 释放预留；EXPIRE 移除到期剩余额度。',interaction:'预留与消费不能相加为两次扣费。详情展示先到期分配及业务引用。'}]},
orders:{title:'Orders',description:'Payment state and fulfillment state are recorded separately.',loader:listOrders,notes:[{title:'支付和履约',rule:'支付失败不发权益；已支付但履约失败允许补发。重试使用原购买快照，不能按最新规则重发或重复发放。',interaction:'Retry Delivery 只对已支付未完成订单开放。模拟下单及支付结果仅放在 Flow Preview。'}]},
subscriptions:{title:'Subscriptions',description:'Paid periods retain their purchased rules.',loader:listSubscriptions,notes:[{title:'取消续订',rule:'关闭续订保留当前已购周期和原权益。到期才限制新的会员功能；已有资产保留。',interaction:'取消/恢复均填写原因；已过期周期不能直接恢复，要发起新购买。商店回调在演示中使用适配器。'}]},
redemptions:{title:'Content Redemptions',description:'Independent content assets purchased with Credits or migrated from Star.',loader:listRedemptions,notes:[{title:'独立权益',rule:'兑换锁定内容、价格和期限；会员到期不影响有效兑换。相同内容的有效兑换不会重复收费。',interaction:'详情区分 Credits 和 legacy_star；用户购买页查询已有权益后再确认。'}]},
usage:{title:'Service Requests',description:'Reserved → completed or released. Saved results can be reopened.',loader:listUsage,notes:[{title:'请求状态',rule:'一次用户操作预留一次；成功结算并保存结果，失败或租约超时释放。重复完成不重复扣费。',interaction:'本查询页只展示请求状态和已有结果；完成与失败由服务端回调驱动。人工模拟 Complete / Release 仅放在 Flow Preview。'}]},
'campaign-runs':{title:'Benefit Delivery Records',description:'Recipients, published version, case and delivery result.',loader:listCampaignRuns,notes:[{title:'发放记录',rule:'成功和重复跳过分别记录。活动按用户去重，补偿按案件和用户去重。',interaction:'查看详情追踪实际授权和额度批次，不覆盖原购买记录。'}]},
audit:{title:'Audit Log',description:'Configuration publication and transactional changes.',loader:listAudit,notes:[{title:'审计范围',rule:'记录配置草稿、发布、支付、履约、发放和服务结算。演示 Admin 为操作人占位，用户是业务主体。',interaction:'详情查看上下文和配置快照。正式接入时由现有登录系统写入真实操作人。'}]}
}
export default{components:{RecordsTable,InteractionNotes},props:{kind:{type:String,required:true}},data(){return{rows:[],users:[],search:'',userId:'',status:'',page:1,loading:false,error:''}},computed:{definition(){return definitions[this.kind]},statuses(){return[...new Set(this.rows.map(r=>r.status||r.type||r.action).filter(Boolean))]},filtered(){return this.rows.filter(r=>(!this.userId||r.userId===this.userId)&&(!this.status||(r.status||r.type||r.action)===this.status)&&JSON.stringify(r).toLowerCase().includes(this.search.toLowerCase()))},pageRows(){return this.filtered.slice((this.page-1)*10,this.page*10)}},watch:{search(){this.page=1},userId(){this.page=1},status(){this.page=1}},created(){this.load()},methods:{async load(){this.loading=true;try{[this.rows,this.users]=await Promise.all([this.definition.loader(),listUsers()]);this.error=''}catch(e){this.error=e.message}finally{this.loading=false}}}}
</script>
